<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 11 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;
public class Solution {
    public static void main(String[] args) throws IOException {
        FastReader fr = new FastReader();
        int n = fr.nextInt();
        int k = fr.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = fr.nextInt();
        int even = 0, odd = 0;
        int[] gaps = new int[n]; // max possible
        int idx = 0;
        for (int i = 0; i < n; i++) {
            if (i != 0 && even == odd) gaps[idx++] = Math.abs(arr[i] - arr[i-1]);
            if (arr[i] % 2 == 0) even++;
            else odd++;
        }
        int[] actual = Arrays.copyOf(gaps, idx);
        Arrays.sort(actual);
        int count = 0;
        for (int g : actual) {
            if (g <= k) { count++; k -= g; }
            else break;
        }
        System.out.println(count);
    }
    // Unused methods removed
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        public FastReader() { br = new BufferedReader(new InputStreamReader(System.in)); }
        String next() { while (st == null || !st.hasMoreElements()) { try { st = new StringTokenizer(br.readLine()); } catch (IOException e) { e.printStackTrace(); } } return st.nextToken(); }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        String nextLine() { String str = ""; try { str = br.readLine(); } catch (IOException e) { e.printStackTrace(); } return str; }
    }
}
